import { Component, OnInit, OnDestroy, Output, EventEmitter, ElementRef, Renderer2 } from '@angular/core';

@Component({
  selector: 'app-splash-screen',
  templateUrl: './splash-screen.component.html',
  styleUrls: ['./splash-screen.component.css']
})
export class SplashScreenComponent implements OnInit, OnDestroy {
  @Output() splashDone = new EventEmitter<void>();

  isExiting = false;
  isHidden = false;
  particles: { left: string; duration: string; delay: string; size: string }[] = [];

  private splashTimeout: any;
  private hideTimeout: any;

  constructor(private el: ElementRef, private renderer: Renderer2) {}

  ngOnInit(): void {
    // Generate particles data
    for (let i = 0; i < 30; i++) {
      this.particles.push({
        left: Math.random() * 100 + '%',
        duration: (4 + Math.random() * 6) + 's',
        delay: (Math.random() * 5) + 's',
        size: (2 + Math.random() * 4) + 'px'
      });
    }

    // Prevent body scroll while splash is visible
    this.renderer.setStyle(document.body, 'overflow', 'hidden');

    // Start exit after splash duration (total ~3.0s: 2500ms active + 500ms fade exit)
    this.splashTimeout = setTimeout(() => {
      this.isExiting = true;

      // After exit animation completes, hide and notify parent
      this.hideTimeout = setTimeout(() => {
        this.isHidden = true;
        this.renderer.removeStyle(document.body, 'overflow');
        this.splashDone.emit();
      }, 500);
    }, 2500);
  }

  ngOnDestroy(): void {
    clearTimeout(this.splashTimeout);
    clearTimeout(this.hideTimeout);
    this.renderer.removeStyle(document.body, 'overflow');
  }
}

<div class="splash-screen"
     [class.exit]="isExiting"
     [class.hidden]="isHidden">

  <!-- Animated background orbs -->
  <div class="splash-orb splash-orb--1"></div>
  <div class="splash-orb splash-orb--2"></div>
  <div class="splash-orb splash-orb--3"></div>

  <!-- Floating particles -->
  <div class="particles">
    <div class="particle"
         *ngFor="let p of particles"
         [style.left]="p.left"
         [style.animationDuration]="p.duration"
         [style.animationDelay]="p.delay"
         [style.width]="p.size"
         [style.height]="p.size">
    </div>
  </div>

  <!-- Content -->
  <div class="splash-logo-container">
    <div class="splash-icon-ring">
      <i class="fa-solid fa-briefcase"></i>
    </div>

    <div class="splash-brand">CareerHub</div>

    <div class="splash-tagline">Where Talent Meets Opportunity</div>

    <div class="splash-keywords">
      <span class="splash-keyword"><i class="fa-solid fa-magnifying-glass"></i> Smart Job Matching</span>
      <span class="splash-keyword"><i class="fa-solid fa-bolt"></i> Instant Apply</span>
      <span class="splash-keyword"><i class="fa-solid fa-chart-line"></i> Career Growth</span>
      <span class="splash-keyword"><i class="fa-solid fa-users"></i> Top Companies</span>
      <span class="splash-keyword"><i class="fa-solid fa-globe"></i> Remote Ready</span>
    </div>

    <div class="splash-loader">
      <div class="splash-loader-bar"></div>
    </div>
  </div>
</div>
